// Clean up "ruhsatlı ve tavsiyelidir" from DEFAULT_BKU_DATABASE
DEFAULT_BKU_DATABASE.forEach(item => {
    if (item && item.uyari) {
        item.uyari = item.uyari.replace(/\.?\s*Ruhsatl[ıi]\s+ve\s+tavsiyelidir\.?/gi, "").trim();
        if (item.uyari.endsWith(".")) {
            item.uyari = item.uyari.slice(0, -1).trim();
        }
    }
});

if (typeof window !== 'undefined') {
    window.DEFAULT_BKU_DATABASE = DEFAULT_BKU_DATABASE;
}
